/** Picks the curated block for the given rashi + language, or null if none. */
export function getCuratedPrediction(
  rashiId: number,
  lang: "mr" | "en" | "hi" = "mr",
): CuratedPrediction | null {
  const entry = CURATED[rashiId];
  if (!entry) return null;
  const pickField = (f: { mr: string; en?: string; hi?: string }) => ({
    mr: f.mr,
    en: f.en ?? f.mr,
    hi: f.hi ?? f.mr,
  });
  void lang;
  return {
    overall: pickField(entry.overall),
    career:  pickField(entry.career),
    love:    pickField(entry.love),
    health:  pickField(entry.health),
  };
}
